insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('forecastml', 'intermediate', 'module', 'm01-forecast-errors', 1, 'On the teaching hold-out, holt''s forecast for month 36 is 282.531964 and the well made 270.100000. The engine prints the error as -12.431964. What does the sign say?', '["That holt under-forecast the month, since a minus sign marks a forecast that fell short of the well", "The forecast sat 12.431964 bbl/d above the rate the well made", "Nothing about direction; the engine prints every error as a magnitude with a sign of its own choosing", "The actual came in 12.431964 bbl/d above the forecast"]'::jsonb, 1, 'The engine''s basis reads "e = actual - forecast", so 270.100000 less 282.531964 is negative and a negative error means the forecast was high. An under-forecast would give a positive error. The sign is fixed by that rule and carries meaning, and the actual sat below the forecast here, never above it.'),
  ('forecastml', 'intermediate', 'module', 'm01-forecast-errors', 2, 'Holt''s error for month 38 of the teaching hold-out is 3.128846. Which reading of that figure is right?', '["Holt forecast month 38 high, sitting 3.128846 bbl/d above the actual rate", "The fit missed month 38 by 3.128846 bbl/d, in a direction no error can ever show", "A one-step residual of 3.128846 bbl/d that the fit chose its parameters on", "Holt forecast month 38 low: the well made 3.128846 bbl/d more than forecast"]'::jsonb, 3, 'An error is actual minus forecast: 271.500000 less 268.371154 is 3.128846, positive, so the forecast was low. A high forecast gives a negative error, and the sign shows the direction. Month 38 is a hold-out month the fit never saw, so this is an out-of-sample error and no residual; a residual is an in-sample one-step error.'),
  ('forecastml', 'intermediate', 'module', 'm01-forecast-errors', 3, 'On the teaching hold-out ses prints ME -51.683333 and MAE 51.683333. What must be true of its 12 errors?', '["Their positive and negative values cancel, leaving a mean of zero behind the bias", "About half are negative, and the ME simply happens to match the MAE in size on this well", "Each is exactly -51.683333, because a flat forecast misses every month by the same amount", "Every one of them is negative: the flat forecast sat above each month of the decline"]'::jsonb, 3, 'The ME equals minus the MAE only when no error is positive, so all 12 ses errors are negative: its forecast 290.700000 sits above every month from 36 to 47. They do not cancel, since the mean is -51.683333 and far from zero. The errors differ month by month because the actuals fall from 270.100000 to 211.400000 while the forecast stays flat.'),
  ('forecastml', 'intermediate', 'module', 'm01-forecast-errors', 4, 'Holt on the teaching hold-out has ME -4.573069 and MAE 6.783515. Why is the size of the ME smaller than the MAE?', '["The ME divides by more errors than the MAE does, which shrinks it on every hold-out", "Some holt errors are positive and some negative, so they partly cancel in the mean", "Holt''s forecast is low on average, and a low forecast always makes the ME the smaller one", "RMSE absorbs the large errors first, leaving only the small ones for the ME to average"]'::jsonb, 1, 'Holt''s errors include positive ones (3.128846 at month 38, 6.752492 at month 47) and negative ones (-13.910343 at month 40), so the signed mean partly cancels while the absolute mean does not. Both divide by the same 12 errors. The negative ME says holt was high on average, and RMSE is a separate metric that takes nothing from the ME.'),
  ('forecastml', 'intermediate', 'module', 'm01-forecast-errors', 5, 'The teaching hold-out prints holt''s MAE as 6.783515 and its RMSE as 8.360530. What makes the RMSE the larger figure?', '["RMSE divides by n less one, as a sample deviation does, which lifts it", "Its unit is bbl/d squared, so the same misses print as a larger figure", "Only the negative errors count, and those are the larger ones on this hold-out", "Squaring weights the large errors more heavily than the small ones"]'::jsonb, 3, 'RMSE is "sqrt(mean e^2)", and squaring gives a large error more weight, so RMSE is at least MAE on every row the course prints. Its divisor is n, the number of errors scored, with nothing taken away. The square root returns it to bbl/d, and it uses every error whatever its sign.'),
  ('forecastml', 'intermediate', 'module', 'm01-forecast-errors', 6, 'A learner scores holt on the teaching hold-out and wants the RMSE divisor. What does the engine divide the sum of squared errors by before taking the root?', '["12, the number of errors scored on months 36 to 47", "11, the number of errors less one, the way a sample standard deviation is taken", "36, the number of training months the fit was chosen on before the hold-out", "46, the scored in-sample residuals"]'::jsonb, 0, 'The divisor of RMSE is n, the number of errors scored, and the hold-out scores 12 months. The engine takes no degree of freedom away. The 36 training months and the in-sample residuals are the fit''s business and are never counted in a hold-out metric.'),
  ('forecastml', 'intermediate', 'module', 'm01-forecast-errors', 7, 'Fitted on EKENE-P1 months 0 to 35, damped has the lowest in-sample one-step MAE, 19.150711, while holt has the lowest hold-out MAE, 6.783515. Which method does the course judge better at forecasting those 12 months, and on which figure?', '["Damped, on its in-sample MAE of 19.150711", "Holt, whose out-of-sample MAE is the lowest of the three", "Neither, until the two MAEs agree", "Ses, since its in-sample figure 28.045714 is the steadiest of the three on the training months"]'::jsonb, 1, 'The in-sample figure scores one-step forecasts on months that chose the parameters; the hold-out scores forecasts up to 12 steps ahead on months the fit never saw. A method is judged on the second, and holt''s 6.783515 is the lowest there. The two figures answer different questions and need not agree, and ses has the highest in-sample MAE of the three.'),
  ('forecastml', 'intermediate', 'module', 'm01-forecast-errors', 8, 'Why can the in-sample one-step MAE flatter a method against its hold-out MAE?', '["In-sample errors exclude every negative residual, so only the smaller misses are averaged", "The engine rounds in-sample residuals to one decimal, which trims each error a little", "The in-sample months chose the parameters and fed the state, and each is only one step ahead", "Fitted months are rescaled by the MASE scale before the mean is taken, shrinking them"]'::jsonb, 2, 'In-sample, the months scored helped pick alpha and beta and fed the level and trend, and every forecast looks one month ahead. The hold-out looks up to 12 months ahead from one fixed month on months that reached the fit in no way. Residuals keep their sign and their six-decimal value, and no scale is applied to an MAE.'),
  ('forecastml', 'intermediate', 'module', 'm01-forecast-errors', 9, 'Holt fitted on months 0 to 35 is scored on months 36 to 47. Which error has the largest size?', '["At month 37, where holt sat 13.551559 bbl/d above the well", "The twelfth step, month 47, since error grows with the step", "Month 40, where the error is -13.910343", "Step 1, month 36, at -12.431964"]'::jsonb, 2, 'The holt errors run -12.431964, -13.551559, 3.128846, -12.690748, -13.910343 and on to 6.752492 at month 47. The largest in size is -13.910343 at month 40. Month 37''s -13.551559 is a little smaller, month 47''s 6.752492 is far smaller, and the course shows the errors do not grow in order with the step.'),
  ('forecastml', 'intermediate', 'module', 'm01-forecast-errors', 10, 'Damped on the teaching hold-out prints ME -14.978829 and MAE 14.978829. What does that pair say about damped''s forecast?', '["It sat above the well in every month from 36 to 47", "Below the well each month, as damping flattens it low", "One crossing of the actuals, so the errors cancel out", "Exact at month 36, then high on each later month after"]'::jsonb, 0, 'The ME equals minus the MAE only when every error is negative, so damped''s forecast was high in each of the 12 months: 283.622932 against 270.100000 at month 36, and 228.161212 against 211.400000 at month 47. Its flattening kept it above a well that went on declining, and month 36 carries an error of its own, far from exact.'),
  ('forecastml', 'intermediate', 'module', 'm01-forecast-errors', 11, 'A learner passes `accuracy` three actuals and two forecasts. What comes back?', '["Metrics computed on the first two months, with the unmatched third actual left out of each", "An ME and an MAE, with RMSE returned as null and its reason given in the notes", "A refusal naming `forecast`: \"forecast must have 3 values, one per actual (it has 2)\"", "Its three metrics scored against a third forecast of zero that the engine fills in"]'::jsonb, 2, 'The engine refuses and names the field, in its own words: "forecast must have 3 values, one per actual (it has 2)". Forecasts are scored one for one against actuals, so nothing is trimmed or filled. A null metric with a reason in `notes` is a result, and this call returns no result at all.'),
  ('forecastml', 'intermediate', 'module', 'm01-forecast-errors', 12, 'In an `accuracy` call the second forecast is null. What does the engine return?', '["A refusal naming `forecast[1]`, which asks for missing values to be filled or dropped first", "An error that the forecast array is short, since a null is read as a missing entry at the end", "Every metric scored on the remaining months, with the null month quietly skipped over", "Each metric returned as null, with the reason for every one of them listed in its notes"]'::jsonb, 0, 'The engine refuses by name at the index, counting from 0, in its own words: "forecast[1] must be a finite number: fill or drop missing values first". The array keeps its length, so no short-array message appears. The engine drops or fills nothing, and a refusal carries no metrics at all, null or otherwise.'),
  ('forecastml', 'intermediate', 'module', 'm01-forecast-errors', 13, 'A learner fits holt on all 48 months of EKENE-P1, forecasts 12 steps and plans to score them against months 36 to 47. What has gone wrong?', '["Nothing; step 1 forecasts month 36 whatever months the fit was made on", "Only the scale: the forecasts are right but MASE needs the training months named", "The forecasts include the months scored, so every error comes out as exactly zero", "Those 12 steps forecast months 48 to 59; step 1, 204.197498, is a forecast for month 48"]'::jsonb, 3, 'A 12-step forecast is a forecast of months 36 to 47 only when it is made from month 35. Fitted on all 48 months, step 1 is one step past the last month, month 48: holt gives 204.197498 there, and no month of the series can score it. The errors would not be zero, because the forecasts are for different months entirely.'),
  ('forecastml', 'intermediate', 'module', 'm01-forecast-errors', 14, 'The course runs holt on EKENE-P1 one step ahead over months 36 to 47 two ways: an honest backtest refitted at each origin gives MAE 8.096036, and a fit on all 48 months scored on its own residuals gives 8.045544. What does the course conclude?', '["The leak is harmless here, because the two MAEs differ by only 0.050492 bbl/d on this well", "The second route leaks, because the months scored chose the parameters, whatever its size", "The honest route is wrong, since its MAE is the higher of the two figures on these months", "Leakage shows itself as a lower MAE, so any route scoring below the honest one leaked"]'::jsonb, 1, 'The rule is procedural: the months scored must never reach the fit. The full-series fit let months 36 to 47 choose alpha and beta and feed the state, so it leaks whatever the number. On one well the size and sign of the 0.050492 bbl/d difference are no test, so a small or a lower figure proves nothing either way.'),
  ('forecastml', 'intermediate', 'module', 'm01-forecast-errors', 15, 'The engine''s basis prints the mean error as "mean e (bias; positive means the forecast is low)". All three methods have ME below 0 on the teaching hold-out. What does that say?', '["Each method forecast EKENE-P1 high over months 36 to 47", "Low forecasts from each method, outrun by the decline", "No bias at all, a negative ME being its mark", "Every error of all three methods is negative"]'::jsonb, 0, 'With the error defined as actual minus forecast, a negative mean says the forecasts sat above the well on average: ses -51.683333, holt -4.573069, damped -14.978829. A low forecast would give a positive ME. Holt''s mean is negative while some of its errors, such as 3.128846 at month 38, are positive, so not every error is negative.'),
  ('forecastml', 'intermediate', 'module', 'm02-percentage-errors', 1, 'Holt on EKENE-P2 is fitted on months 0 to 19 and scored on months 20 to 25, which include the shut-in months 22 to 24 at rate 0. What does the engine return for MAPE?', '["A refusal naming `actual`, since a zero rate cannot be scored by any of the metrics at all", "MAPE over the three producing months only, 20, 21 and 25, with the shut-in months dropped", "200.000000 percent, the top of the scale", "No number: MAPE comes back as null, and the reason goes in `notes`"]'::jsonb, 3, 'MAPE divides by each actual, and a shut-in month has none to divide by, so the engine returns MAPE as null with the reason "MAPE is undefined: actual[2] is 0 and MAPE divides by each actual" in `notes`, in its own words. It is a result with every other metric a number, and no refusal. The engine keeps the month and reports no number for MAPE. The 200.000000 figure is the sMAPE term of a shut-in month, and MAPE has no such top.'),
  ('forecastml', 'intermediate', 'module', 'm02-percentage-errors', 2, 'In that shut-in reason, "MAPE is undefined: actual[2] is 0 and MAPE divides by each actual", which month is actual[2]?', '["Month 22, the first shut-in month, being index 2 of the actuals for months 20 to 25", "The third month on production, month 2, counted from month 0 of the series", "Index 2 read from 1: month 21, the second actual passed", "Month 24, the last of the three shut-in months, where the zero run ends"]'::jsonb, 0, 'An `accuracy` reason names the input, and the actuals passed are months 20 to 25, so index 2, counted from 0, is month 22, the first month at rate 0. Month 2 is outside the actuals scored. Every index in this course counts from 0, so index 2 is never the second actual, and the reason names the first zero it meets.'),
  ('forecastml', 'intermediate', 'module', 'm02-percentage-errors', 3, 'On the same EKENE-P2 hold-out MAPE is null. Which metrics does the engine still return as numbers?', '["MAE 209.968065, RMSE 258.102385, MASE 5.427746 and sMAPE 108.172490", "None: once one metric is null the engine withholds the other metrics of the call as well", "Only sMAPE, 108.172490, because the shut-in months void every metric scaled in bbl/d", "MAE and RMSE alone, as MASE and sMAPE divide by rates and so fail at a zero actual"]'::jsonb, 0, 'A null metric is reported with its reason while the other metrics are still numbers: MAE 209.968065, RMSE 258.102385, MASE 5.427746 and sMAPE 108.172490. MAE and RMSE are in bbl/d and need no division by a rate. sMAPE divides by the sum of the actual and the forecast, and MASE by the training series'' naive error, so neither fails at a zero actual.'),
  ('forecastml', 'intermediate', 'module', 'm02-percentage-errors', 4, 'On that EKENE-P2 hold-out holt forecasts month 23 at 355.679339 and the well made 0.000000. What does month 23 add to sMAPE?', '["A term of 0, since a month with actual 0 is left out of the sum as a zero", "A term of 100 percent, the full size of the error against the forecast alone", "Nothing yet: sMAPE is null for the call, as MAPE is, and so no term is printed", "A term of 200.000000, the top of the scale"]'::jsonb, 3, 'The term is 200 |e| / (|y| + |f|), and with an actual of 0 the error equals the forecast in size, so the term is 200.000000 whatever non-zero forecast is made. Only a term with actual and forecast both 0 scores 0. sMAPE stays a number, 108.172490, while MAPE is null.'),
  ('forecastml', 'intermediate', 'module', 'm02-percentage-errors', 5, 'The stated actuals 0 and 100 are scored twice: with forecasts 0 and 90 sMAPE is 5.263158, and with forecasts 5 and 90 it is 105.263158. What explains the jump?', '["The first run drops the zero month from the mean, while the second run keeps that month and counts it", "A term whose actual and forecast are both 0 scores 0, while forecast 5 on actual 0 scores 200", "Forecast 5 is a larger error in percent than 90 on 100, so the scale doubles for both", "sMAPE switches to MAPE when a forecast of 0 appears, and MAPE reads lower here than sMAPE"]'::jsonb, 1, 'The engine''s rule is that a term with actual = forecast = 0 scores 0, so the first run averages 0 and the 90-on-100 term. A forecast of 5 on an actual of 0 scores the top term, 200, and lifts the mean by 100. No month is dropped, nothing switches metric, and MAPE is null in both runs because the first actual is 0.'),
  ('forecastml', 'intermediate', 'module', 'm02-percentage-errors', 6, 'Stated actual 100: a forecast of 150 scores sMAPE 40.000000, and a forecast of 50 scores 66.666667. MAPE is 50.000000 for both. Why does sMAPE differ?', '["The forecast is in the denominator, so a low forecast shrinks it and the same error costs more", "sMAPE weights an over-forecast as twice as costly, being a measure built to punish high forecasts", "It rounds each term to the nearest third, which shifts the 50 low case up to 66.666667", "It squares the error before it divides, as RMSE does, and so the larger forecast counts less"]'::jsonb, 0, 'sMAPE is 100 x mean 2|e| / (|actual| + |forecast|). Both forecasts miss by 50, but the forecast of 150 makes the larger denominator, so the low forecast scores 66.666667 against 40.000000. The low forecast costs more, the opposite of punishing high forecasts; nothing is rounded or squared.'),
  ('forecastml', 'intermediate', 'module', 'm02-percentage-errors', 7, 'On the teaching hold-out ses reads MAPE 22.550260 and sMAPE 19.852301. Why is its sMAPE the lower of the two?', '["sMAPE is held to 100 percent, which trims ses''s largest monthly terms before the mean", "MAPE includes the training months 0 to 35 as well as the scored months, lifting it", "It is lower by chance; the two metrics move independently of the forecast''s direction", "Ses forecast every month high, and a high forecast enlarges the sMAPE denominator"]'::jsonb, 3, 'Every ses error on months 36 to 47 is negative, so its flat forecast 290.700000 sits above each actual. sMAPE divides by |actual| + |forecast|, which a high forecast enlarges, while MAPE divides by the actual alone. sMAPE runs on 0 to 200 with no ceiling at 100, and both metrics score only the 12 hold-out months.'),
  ('forecastml', 'intermediate', 'module', 'm02-percentage-errors', 8, 'Holt on EKENE-P5''s low tail (fitted on months 0 to 35, scored on 36 to 47) has MAE 3.244769 bbl/d and MAPE 24.095758. On EKENE-P1''s hold-out its MAE is 6.783515 bbl/d and MAPE 2.781120. How can the smaller MAE carry the larger MAPE?', '["MAPE on EKENE-P5 is lifted by the well''s shut-in months, which score 200 each on the low tail", "Holt fits worse in-sample on EKENE-P5, and MAPE carries the in-sample error forward", "EKENE-P5''s rates run from 24.600000 to 11.100000 bbl/d, so a small miss is a large share", "MAPE is scaled by the training months'' naive error, which is small on a steep well"]'::jsonb, 2, 'MAPE divides each error by its actual, and EKENE-P5''s actuals on months 36 to 47 are only 24.600000 down to 11.100000 bbl/d, so errors small in bbl/d are large in percent. EKENE-P5 has no shut-in; MAPE uses only the scored months; and the naive scale belongs to MASE, never to MAPE.'),
  ('forecastml', 'intermediate', 'module', 'm02-percentage-errors', 9, 'What does the course say a percentage error is good for, and where does it mislead?', '["No need to state the months scored follows from it, and it misleads only when a forecast is high", "It puts wells of different size on one scale, and on a low tail it is large for small misses", "Rate size leaves it unaffected, and it misleads only on wells with a plateau", "Bias is what it measures, and it misleads when positive and negative errors cancel"]'::jsonb, 1, 'Dividing by the actual puts a large well and a small one on one scale, and the same division makes a percentage large where the rate is low, as on EKENE-P5''s tail. A metric still names its months. The size of the rate is exactly what a percentage depends on, and bias is the ME''s job, since percentage errors use absolute values.'),
  ('forecastml', 'intermediate', 'module', 'm02-percentage-errors', 10, 'On EKENE-P5''s low tail damped reads MAE 12.689466 bbl/d, MAPE 84.152526 and sMAPE 57.006610; holt reads MAE 3.244769, MAPE 24.095758 and sMAPE 32.408520. Which statement holds?', '["Holt''s sMAPE is above its MAPE while damped''s is below, yet holt is lower on all three metrics", "Damped is lower by sMAPE, since that metric treats a low tail more kindly than MAPE does", "The two methods are tied by sMAPE, both landing in the same band on this tail", "Holt is lower by MAPE and MAE, but damped is lower once the error is made symmetric"]'::jsonb, 0, 'Holt reads 3.244769, 24.095758 and 32.408520 against damped''s 12.689466, 84.152526 and 57.006610, lower on every metric. Holt''s sMAPE 32.408520 is above its MAPE 24.095758, and damped''s 57.006610 is below its 84.152526. No reading makes damped lower or the two tied.'),
  ('forecastml', 'intermediate', 'module', 'm02-percentage-errors', 11, 'What range does the engine''s sMAPE run over, and what is its basis?', '["0 to 100 percent, halving the two-sided sum so a total miss reads 100", "Minus 200 to 200, since the sign of each error is kept in the numerator", "0 to 200 percent, as \"100 x mean 2|e| / (|actual| + |forecast|)\"", "Unbounded above, since a forecast far above a small actual has no ceiling"]'::jsonb, 2, 'The engine''s basis reads "100 x mean 2|e| / (|actual| + |forecast|), percent on 0 to 200; a term with actual = forecast = 0 scores 0". Absolute values keep every term at or above 0, and the largest a term can be is 200, reached when one of actual and forecast is 0. A 0 to 100 version is another convention, which this engine does not use.'),
  ('forecastml', 'intermediate', 'module', 'm02-percentage-errors', 12, 'A backtest of ses on EKENE-P2 from first origin 20, with horizon 3 and step 6, has the shut-in in its actuals. Which reason does it give for MAPE?', '["\"MAPE is undefined: actual[2] is 0 and MAPE divides by each actual\", the reason `accuracy` gives", "A refusal naming `firstOrigin`, because an origin before a shut-in cannot be scored at all", "No reason, since a backtest drops the zero months and returns a MAPE over the rest", "\"MAPE is undefined: the actual at index 22 (origin 20, step 3) is 0 and MAPE divides by each actual\""]'::jsonb, 3, 'A backtest reason names the origin it comes from, while an `accuracy` reason names the input, which is why the index here is 22 of the series with origin 20 and step 3 beside it. MAPE is returned as null with that reason and the call is not refused; the engine drops no month.'),
  ('forecastml', 'intermediate', 'module', 'm02-percentage-errors', 13, 'Holt''s term of sMAPE on EKENE-P2 month 25, after the shut-in, is 34.293958. What made it large?', '["The actual was 0, and a zero actual always scores the top term of 200 on the scale", "The error was negative, and sMAPE doubles each term in which the forecast ran high", "The rate came back at 456.100000 while holt forecast 322.579918, an error of 133.520082", "Its forecast was 0.000000, so the denominator held only the actual 456.100000"]'::jsonb, 2, 'Month 25 is back on production at 456.100000, and holt, fitted on months before the shut-in, forecast 322.579918: an error of 133.520082, forecast low. 200 x 133.520082 / (456.100000 + 322.579918) gives the term 34.293958. The actual is not 0, the error is positive, and the forecast is far from 0.'),
  ('forecastml', 'intermediate', 'module', 'm02-percentage-errors', 14, 'Holt on the teaching hold-out reads MAPE 2.781120 and sMAPE 2.735957. Which reading of the pair is right?', '["MAPE is in bbl/d and sMAPE in percent, so they cannot be compared directly at all", "Both are in percent, and each describes months 36 to 47 of EKENE-P1 for holt", "Their small gap proves every holt error on the hold-out is the same size and sign", "They are close because both divide each error by the naive in-sample scale"]'::jsonb, 1, 'MAPE and sMAPE are both percentages, and a percentage is named with its months: here months 36 to 47 for holt fitted on months 0 to 35. Holt''s errors run from -13.910343 to 6.752492, mixing sizes and signs, and neither metric uses the naive scale, which is MASE''s.'),
  ('forecastml', 'intermediate', 'module', 'm02-percentage-errors', 15, 'Why does the engine return MAPE as null at a zero actual and keep the month in the call?', '["Dropping it would need a refit, and MAPE is never allowed to refit the method used", "A null is the engine''s way of refusing the whole call when any input is at zero", "A shut-in month is real, and dropping it would change what the metric measures", "The zero is always a data error, so the engine flags it and waits for a fill"]'::jsonb, 2, 'Removing a month would change what MAPE measures, and a shut-in is part of the well''s record, so the engine keeps it and gives no figure. No refit is involved in scoring, the call itself is answered with its other metrics, and the zero is read as production data that needs no fill.'),
  ('forecastml', 'intermediate', 'module', 'm03-the-scaled-error', 1, 'On the teaching hold-out the engine prints `maseScale` 28.045714 bbl/d. What is that figure?', '["The MAE of the lag-1 naive forecast scored on the hold-out months 36 to 47 themselves", "Holt''s own in-sample one-step MAE on months 0 to 35, the fit''s residuals averaged", "The mean rate of the training months, which turns each error into a share of production", "The mean of |y_t - y_(t-1)| over months 1 to 35 of the training series, 35 differences"]'::jsonb, 3, 'MASE''s Q is the MAE the lag-m naive forecast makes on the training series, in-sample: here the mean of the 35 month-to-month differences over months 1 to 35. The hold-out months never set the scale. Holt''s in-sample MAE is 19.755951, a different figure, and a mean rate would make a percentage, which MASE is not.'),
  ('forecastml', 'intermediate', 'module', 'm03-the-scaled-error', 2, 'Holt''s MAE on the teaching hold-out is 6.783515 bbl/d. With Q 28.045714 at m 1, what MASE does the engine print, and what does it say?', '["0.241874: holt''s mean absolute error is about a quarter of the in-sample naive error", "0.902281, the hold-out''s own naive error taken as the scale, so holt nearly matched it", "1.842825, which says holt did worse than the naive forecast made on the training months", "0.024087, holt''s MASE at m 12, which is the lag the engine takes when none is given"]'::jsonb, 0, 'MASE is "mean |e| / Q", and 6.783515 over 28.045714 is 0.241874, below 1, so holt''s MAE is smaller than the in-sample naive MAE. 0.902281 comes from scaling by the scored months'' own naive error, which is no MASE, and 0.024087 is the m 12 figure, while m defaults to 1. 1.842825 is ses''s MASE on the same hold-out.'),
  ('forecastml', 'intermediate', 'module', 'm03-the-scaled-error', 3, 'Ses on the teaching hold-out has MASE 1.842825. What does a MASE above 1 say?', '["Its mean absolute error is larger than the lag-1 naive forecast''s in-sample MAE", "That ses forecast every hold-out month more closely than the naive did", "A MASE above 1 can only come from a shut-in month in the actuals being scored by the metric", "That the scale was taken from the hold-out months, which the engine does when a method is flat"]'::jsonb, 0, 'MASE below 1 means the forecast''s MAE is smaller than the in-sample naive error, so above 1 means it is larger: ses''s 51.683333 against Q 28.045714. EKENE-P1 has no shut-in, and the engine always takes the scale from the training series, never from the scored months.'),
  ('forecastml', 'intermediate', 'module', 'm03-the-scaled-error', 4, 'A learner scales holt''s hold-out errors by the naive error of months 36 to 47 themselves and gets 0.902281. Why is that no MASE?', '["The naive error of the hold-out months is always zero on a decline, so the division cannot run", "MASE''s scale comes from the training series, so the figure no longer depends on the forecast months", "It is MASE: taking the scale from the scored months is the engine''s default at m 1", "Using hold-out months as the scale is allowed only when the step ahead is 1, and here it runs to 12"]'::jsonb, 1, 'MASE divides by the lag-m naive MAE of the TRAINING series; scaled by the scored months'' own naive error, the scale then depends on the months being forecast, and holt would read 0.902281 against the engine''s 0.241874. That naive error is not zero on EKENE-P1''s months 36 to 47, and the engine takes no scale from scored months at any step ahead.'),
  ('forecastml', 'intermediate', 'module', 'm03-the-scaled-error', 5, 'Scored on the same teaching hold-out with m 12, holt''s MASE reads 0.024087. Why is it so much smaller than at m 1?', '["At m 12 the engine scores only every twelfth month of the hold-out, one error in place of 12", "The larger lag makes holt''s own errors smaller, since it refits the method with a seasonal term", "MASE at m 12 is reported per year, so the monthly figure is divided by 12 before printing", "The lag-12 scale Q is 281.625000: on a decline the month a year before is far from this one"]'::jsonb, 3, 'With m 12 the naive forecast is the same month a year before, and on a declining well that month is far from this month, so Q grows to 281.625000 over 24 differences and the same MAE gives a smaller MASE. The errors are the same 12 errors, the engine builds no seasonal smoothing, and nothing is divided by 12. The lag is part of the figure: quote MASE with its m.'),
  ('forecastml', 'intermediate', 'module', 'm03-the-scaled-error', 6, 'At m 12 on the teaching hold-out''s training months 0 to 35, how many differences make up Q?', '["35, as at m 1", "12, one per hold-out month", "24, from month 12 to month 35", "36, since each training month is paired with the month a year earlier"]'::jsonb, 2, 'At lag 12 a difference needs the month 12 before, so the first is at month 12 and the last at month 35: 24 differences, and Q is 281.625000. 35 is the count at m 1; the hold-out months never enter the scale; and the first 12 training months have no month a year before them.'),
  ('forecastml', 'intermediate', 'module', 'm03-the-scaled-error', 7, 'EKENE-P3''s first 9 months are the plateau at 1500.000000 each. Used as the training series, what does `accuracy` return for MASE?', '["Null, because every difference is 0, so Q = 0 and the engine will not divide by it", "A refusal naming `insample`, since a series with no change is not accepted as training data", "Infinity, printed as a very large MASE, since any error over a scale of 0 is unbounded", "0.000000, because the naive forecast is perfect and any method matched against it scores 0"]'::jsonb, 0, 'Every training difference is 0, so the scale is 0 and MASE would divide by zero; the engine returns null and says so: "MASE is undefined: insample has 9 values and the lag-1 naive forecast has zero in-sample error on them (every y[t] - y[t - 1] is 0), so the scale is 0". That is a result with the other metrics still numbers, and no refusal; no infinite or zero figure is printed.'),
  ('forecastml', 'intermediate', 'module', 'm03-the-scaled-error', 8, 'A learner passes `accuracy` an insample of one month. What does it return for MASE?', '["A refusal naming `insample`, as at least 2 training values are required", "Null, with the reason that the lag-1 naive forecast needs more than 1 value", "MASE computed on a scale of 0, printed as 0.000000 for every forecast", "The MAE itself, since a one-month training series leaves the scale at 1"]'::jsonb, 1, 'The engine returns MASE as null, in its own words: "MASE is undefined: insample has 1 value, so the lag-1 naive forecast has no in-sample error (it needs more than 1)". A single value has no naive difference at all. An insample of one value is accepted; only an empty one is refused. No scale of 0 or 1 is assumed.'),
  ('forecastml', 'intermediate', 'module', 'm03-the-scaled-error', 9, 'One `accuracy` call is passed no insample at all, and another is passed an empty insample. How do the two results differ?', '["Both are refused in the same words, since neither gives a training series to scale by", "The first returns MASE as null with a reason; the second is refused, naming `insample`", "Both return MASE as null, with the same reason in notes, and every other metric a number", "The first is refused for the missing field, and the second returns MASE as a null metric"]'::jsonb, 1, 'Leaving insample out is allowed: MASE comes back null with the reason "MASE needs insample (the training series) to scale by its in-sample naive error". An empty insample is refused: "insample has 0 values: at least 1 value is needed".'),
  ('forecastml', 'intermediate', 'module', 'm03-the-scaled-error', 10, 'A learner passes `accuracy` a lag m of 0. What comes back?', '["MASE scaled by the forecast''s own errors, since a lag of 0 compares each month with itself and so leaves the naive forecast with no difference to average", "MASE returned as null, with a reason in `notes` saying the lag-0 naive forecast has no in-sample error, while ME, MAE, RMSE, MAPE and sMAPE stay numbers", "Each metric computed with m reset to 1, the default, and a warning in the result that the lag passed was changed before the naive scale was taken", "A refusal naming `m`, in the engine''s words \"m must be a whole number, 1 or more (1 is the non-seasonal naive; 12 is a monthly seasonal naive)\""]'::jsonb, 3, 'A lag of 0 is refused by name with that message. Nothing is rescaled or reset: a refusal returns no metrics, and a null with a reason is kept for a scale the arithmetic cannot give, such as a flat training window.'),
  ('forecastml', 'intermediate', 'module', 'm03-the-scaled-error', 11, 'With m set to 12, a training series of exactly 12 months is handed to `accuracy`. How does the scaled error come back?', '["A MASE scaled by a single difference, the last month less the first of the training months", "A refusal naming `m`, since the lag may not equal the length of the training series", "The same figure as at m 1, as the engine falls back to lag 1 when the series is short", "Null: a lag-12 naive forecast needs more than 12 training values"]'::jsonb, 3, 'The reason reads "MASE is undefined: insample has 12 values, so the lag-12 naive forecast has no in-sample error (it needs more than 12)". Twelve months give no pair a year apart, so there is no difference at all. The call is not refused, and the engine does not change the lag.'),
  ('forecastml', 'intermediate', 'module', 'm03-the-scaled-error', 12, 'On EKENE-P5''s low tail holt scores MASE 0.144157 and MAE 3.244769 bbl/d, while on EKENE-P1''s hold-out holt scores MASE 0.241874 and MAE 6.783515. Why can MASE be set side by side across two wells of such different size?', '["It has no unit, each well''s error divided by that well''s own in-sample naive error", "In bbl/d like the MAE, so the two wells'' figures can be subtracted directly", "A percentage of each month''s rate, so a small well and a large one share a scale", "Both wells share one scale Q, since the engine takes it from the field''s largest well"]'::jsonb, 0, 'MASE is the MAE over Q, and Q is that well''s own lag-m naive MAE on its training months, so the ratio has no unit and wells of any size compare. It is neither in bbl/d nor a percentage of rate; a percentage error divides by the actual, and every well carries its own scale.'),
  ('forecastml', 'intermediate', 'module', 'm03-the-scaled-error', 13, 'On the EKENE-P2 hold-out with the shut-in months in the actuals, MAPE is null. What happens to MASE on the same call?', '["Null too: a zero actual voids every metric that divides by anything", "200.000000, the same top term a shut-in month takes in sMAPE", "It is a number, 5.427746, because its scale comes from the training months", "Refused, since the shut-in months fall inside the training window"]'::jsonb, 2, 'MASE divides by Q, the naive MAE of months 0 to 19, and those have non-zero differences, so the zero actuals scored do not touch the scale: MASE is 5.427746. The shut-in months are in the scored months 20 to 25, outside the training window, and only MAPE divides by each actual. 200.000000 is an sMAPE term.'),
  ('forecastml', 'intermediate', 'module', 'm03-the-scaled-error', 14, 'Fitted on months 0 to 35 of EKENE-P1, damped misses months 36 to 47 by 14.978829 bbl/d on average. Which scaled error belongs to it?', '["0.241874, one MASE for all", "0.534086, its MAE over Q 28.045714", "1.842825, as damped and ses share a flat forecast on this well", "14.978829, as MASE equals MAE when the training months set the scale"]'::jsonb, 1, 'MASE is MAE / Q, and 14.978829 over 28.045714 is 0.534086. The scale is shared across methods on one hold-out; the MAE is not, so each method has its own MASE: 0.241874 is holt''s and 1.842825 is ses''s. Damped''s forecast declines while ses''s is flat, and dividing by Q changes the figure.'),
  ('forecastml', 'intermediate', 'module', 'm03-the-scaled-error', 15, 'The engine''s basis reads "mean |e| / Q, Q = mean |y_t - y_{t-m}| over the in-sample (training) series (Hyndman and Koehler 2006); null when Q = 0". Which choice does that basis make?', '["It divides by each month''s actual, keeping shut-ins out", "It rescales each error by the method''s own residuals", "The scale is fixed on the training series before any forecast is scored", "Taking the lag-m naive error of the scored months, it lets the forecast set its own yardstick"]'::jsonb, 2, 'Q is the mean lag-m difference over the training series, so the yardstick is set before the forecast is scored and cannot move with the scored months. MASE does not divide by the actuals (MAPE does), it does not use the method''s residuals, and the scored months never enter the scale.'),
  ('forecastml', 'intermediate', 'module', 'm04-rolling-origin-backtests', 1, 'The teaching backtest runs holt on EKENE-P1''s 48 months from first origin 24 with horizon 6 and step 6. Which origins does it score?', '["24, 30 and 36, stopping where the next origin would reach the last month of the series", "24, 30, 36, 42 and 48, one every 6 months up to the end of the series", "24, 30, 36 and 42", "Every month from 24 to 42, since the step sets only how far each forecast looks ahead"]'::jsonb, 2, 'The origins run 24, 24 + 6 and on while o + 6 <= 48, so the last is 42, whose 6 actuals are months 42 to 47. Origin 42 is accepted because 42 + 6 = 48. Origin 48 has no actuals at all, and the step is the distance between origins, while the horizon sets how far each forecast looks.'),
  ('forecastml', 'intermediate', 'module', 'm04-rolling-origin-backtests', 2, 'In the teaching backtest, which months is the method fitted on at origin 30?', '["Months 24 to 29, a fixed window sliding on", "All 48 months, with 30 to 35 scored later", "Months 0 to 29, and it forecasts months 30 to 35", "Months 6 to 29, the last window moved on"]'::jsonb, 2, 'The window expands from month 0: at origin o the method is fitted on months 0 to o - 1 only, so origin 30 trains on months 0 to 29 and forecasts months 30 to 35. The engine''s basis reads "expanding window: origin o trains on y[0..o-1] and forecasts y[o..o+5]". A sliding window would drop early months, and fitting on all 48 would let the scored months reach the fit.'),
  ('forecastml', 'intermediate', 'module', 'm04-rolling-origin-backtests', 3, 'With refit true, holt''s alpha is 0.684236 at origin 24 and 0.655079 at origin 42. Why does it move?', '["The engine lowers alpha by a fixed amount at every origin to damp the later forecasts", "Alpha is carried from the first window and drifts through rounding over the four origins", "Refit re-estimates beta only, and alpha follows it through the trend update each time", "Each window is a different series, and the free parameters are re-estimated on each one"]'::jsonb, 3, 'With refit true the basis reads "free parameters re-estimated at every origin", and each expanding window adds months, so the least-SSE alpha and beta move: 0.684236 and 0.379743 at origin 24, 0.655079 and 0.393438 at origin 42. No fixed step is applied, nothing is carried from the first window when refitting, and both parameters are re-estimated.'),
  ('forecastml', 'intermediate', 'module', 'm04-rolling-origin-backtests', 4, 'The teaching backtest is rerun with refit false. What parameters does origin 36 use?', '["Alpha 0.663079 and beta 0.398667, fitted at that origin", "The full-series parameters, held at every origin", "Alpha 0.684236 and beta 0.379743, estimated once on the first window", "Whatever alpha and beta the learner last passed, with nothing estimated"]'::jsonb, 2, 'With refit false the basis reads "free parameters estimated on the first window and held at every later origin", so every origin carries the origin 24 values, alpha 0.684236 and beta 0.379743. 0.663079 and 0.398667 are the refitted origin 36 values. The full series never reaches the parameters, and free parameters are still estimated, once.'),
  ('forecastml', 'intermediate', 'module', 'm04-rolling-origin-backtests', 5, 'Refitted, the teaching backtest''s MASE is 0.374515; with parameters held from the first window it is 0.368974. Which is the honest test?', '["Both, since at every origin only months before the origin were used", "Only the refitted run, as held parameters let later months in", "The held run alone, having the lower MASE", "Neither, until the two figures agree"]'::jsonb, 0, 'Held parameters are cheaper and test one parameter set on later data; refitting tests the whole procedure as it would be run each month. Either is honest, because at every origin only months before the origin were used. The held parameters come from the first window, so no later month enters, and a lower figure is no proof of honesty. Say which was run.'),
  ('forecastml', 'intermediate', 'module', 'm04-rolling-origin-backtests', 6, 'With refit false, how do origin 24''s errors compare with the refitted run''s?', '["They differ at every step, since holding the parameters changes the first forecast too", "Every error is larger, nothing having been estimated", "They are the same, since both runs fit the first window the same way", "They match at step 1 only, and the later steps of origin 24 then drift apart"]'::jsonb, 2, 'The held run estimates its parameters on the first window, which is exactly what the refitted run does at origin 24, so the first origin''s errors are the same (11.627690 at step 1 on to 31.937659 at step 6); later origins differ. The held parameters are estimated from data, once, and nothing differs inside origin 24.'),
  ('forecastml', 'intermediate', 'module', 'm04-rolling-origin-backtests', 7, 'Holt on EKENE-P1 with horizon 6 is started at origin 2. What does the engine say?', '["It refuses: \"firstOrigin must be a whole number from 3 to 42 (''holt'' needs 3 training values; an origin above 42 leaves fewer than 6 actuals)\"", "The origin moves up to 3, the first one holt can fit, and the backtest runs from there to origin 42 with a note in the result saying the first origin was raised", "Origin 2 runs, and month 2 scores a residual of 0, as the fit forecasts that month exactly from its start of l_1 = y_1 and b_1 = y_2 - y_1, before the others", "A refusal naming `horizon`: \"horizon must be a whole number, 1 or more\", since 6 steps from origin 2 run past the training window the call has"]'::jsonb, 0, 'Holt spends its second month on the start, so it needs 3 training values and the lowest origin is 3; the highest is 42, leaving 6 actuals. The engine refuses and names `firstOrigin` in those words. Nothing is moved or run, and the horizon is not the field at fault.'),
  ('forecastml', 'intermediate', 'module', 'm04-rolling-origin-backtests', 8, 'Ses from origin 45 with horizon 6 on EKENE-P1''s 48 months is refused with "firstOrigin must be a whole number from 2 to 42 (''ses'' needs 2 training values; an origin above 42 leaves fewer than 6 actuals)". Why is the lower limit 2 for ses and 3 for holt?', '["Ses needs 2 training values, while holt and damped spend their second month on the start", "Ses may start a month earlier, its flat forecasts being cheap to score", "The lower limit is the horizon divided by 3, and ses runs shorter", "Holt requires a month of warm-up that ses skips, as ses has no parameters to estimate at all"]'::jsonb, 0, 'The limit follows the method''s fitting length: ses needs 2 values, the first to set the level and the second to be the first scored forecast; holt and damped start their trend from the first two months, so they need 3. The upper limit, 42, follows the horizon and the series length. Ses still fits an alpha, and the horizon plays no part in the lower limit.'),
  ('forecastml', 'intermediate', 'module', 'm04-rolling-origin-backtests', 9, 'EKENE-P6, the new well, has 3 months. What does a backtest of holt with horizon 1 return?', '["One origin, 2, scored on month 2, since holt can be fitted on its three months and a horizon of 1 needs only one actual after it", "A refusal: \"y has 3 values: a backtest with horizon 1 needs at least 4 (''holt'' needs 3 training values, then 1 actual)\"", "A backtest of ses in place of holt, the engine choosing the method its length allows and naming the swap in the result", "Pooled metrics that are all null, each with a reason in `notes` naming the short series and the months it would need"]'::jsonb, 1, 'Holt can be fitted on 3 months, but a backtest needs 3 training values and then at least one actual, 4 in all, so it is refused by that length rule in the engine''s words. No origin below 3 exists for holt, the engine never swaps the method, and a refusal carries no metrics.'),
  ('forecastml', 'intermediate', 'module', 'm04-rolling-origin-backtests', 10, 'A backtest is asked for with a horizon of 0. What does the engine return?', '["Every origin''s fitted parameters with no forecasts, as a horizon of 0 asks for none", "The in-sample residuals of each window, as zero-step errors", "Metrics returned as null, each with the reason that no actual was scored at all", "A refusal naming `horizon`: \"horizon must be a whole number, 1 or more\""]'::jsonb, 3, 'A horizon of 0 is refused in the engine''s own words, and the same holds for a step of 0 with "step must be a whole number, 1 or more". A refusal returns no result, so no parameters, residuals or null metrics come back.'),
  ('forecastml', 'intermediate', 'module', 'm04-rolling-origin-backtests', 11, 'On EKENE-P1, holt is fitted on all 48 months, the parameters are held, and a backtest from origin 36 with horizon 1 and step 1 is run. It gives MAE 8.045544 on months 36 to 47, while the honest backtest refitted at each origin gives 8.096036. What leaked?', '["Nothing, as the backtest trains only on months before each origin", "Months 36 to 47 chose the parameters, fitted on all 48 months", "The state and the parameters both, exactly as in the honest run from origin 36", "Only the scale Q, taken from all 48 months"]'::jsonb, 1, 'The parameters were fitted on all 48 months, so months 36 to 47 chose them, and that is a route by which the scored months reach the fit. The state at each origin is still run from months before the origin. The honest run lets nothing leak, and the scale plays no part in an MAE.'),
  ('forecastml', 'intermediate', 'module', 'm04-rolling-origin-backtests', 12, 'The two leaky routes on EKENE-P1 (the full fit scored on its own one-step residuals for months 36 to 47, and full-fit parameters held in a backtest from origin 36) both print MAE 8.045544. Are they the same numbers?', '["Yes: the course checks they are the same error for error, exactly", "Not necessarily; two figures that print alike at six decimals may differ in later digits", "No: the residual route leaks the state and the parameters, so its MAE must be lower", "Yes, but only by chance on this well, as the two routes compute different quantities"]'::jsonb, 0, 'Holding parameters fitted on the whole series and stepping forward one month at a time replays the full fit''s own one-step forecasts, error for error, and the course checked the two are the same exactly before calling them the same. Printing alike alone would not prove it, which is why the check was made; the equality follows from the procedure.'),
  ('forecastml', 'intermediate', 'module', 'm04-rolling-origin-backtests', 13, 'A learner picks test months at random and fits on the others. Why does the course call that leakage?', '["Random months have unequal sizes in bbl/d, which biases the MAE downward", "A random split scores too few months to give a MASE with its own scale", "The engine''s random split reuses one seed, so the same months are always drawn", "The months around each test month, before and after it, are in the fit"]'::jsonb, 3, 'Choosing test months at random and fitting on the rest leaks the future into the past, because later months sit in the fit. The engine offers no random split: a smoothing method needs an unbroken series, and its only honest test is an origin with everything after it held back.'),
  ('forecastml', 'intermediate', 'module', 'm04-rolling-origin-backtests', 14, 'Why is the last origin of the teaching backtest 42 and never 43?', '["The step of 6 lands on 42, and origins may only fall on multiples of the step", "Origin 43 with horizon 6 would need month 48, which the series does not have", "Holt refuses any origin within 6 months of the end, whatever the horizon is", "Origin 43 leaves the training window too long for the compass search to fit it"]'::jsonb, 1, 'Every origin must have all its actuals, so the last is the largest o with o + 6 <= 48: 42 is accepted since 42 + 6 = 48, and 43 would need month 48, one past month 47. The rule turns on the horizon and the series length, multiples of the step play no part, and a long training window is never refused.'),
  ('forecastml', 'intermediate', 'module', 'm04-rolling-origin-backtests', 15, 'At origin 36 of the teaching backtest, holt''s step 1 error is -12.431964. Where else does the course print that same figure?', '["Only in the backtest, as a hold-out fits on all 48 months before it is scored", "As the in-sample residual of month 36 from the fit on all 48 months of EKENE-P1", "In the held run alone, since the refitted run changes the step 1 error at origin 36", "As holt''s month 36 error on the teaching hold-out, fitted on months 0 to 35"]'::jsonb, 3, 'Origin 36 trains on months 0 to 35 and forecasts from there, which is the teaching hold-out, so its step 1 error equals the hold-out''s month 36 error, -12.431964, and the six errors run on to -5.029938 at month 41. The hold-out fits months 0 to 35 only; a full-series residual lets month 36 into the fit; and the held run uses origin 24''s parameters, so its origin 36 errors differ.'),
  ('forecastml', 'intermediate', 'module', 'm05-pooling-backtest-errors', 1, 'How many errors do the teaching backtest''s overall metrics average over?', '["6, one per step ahead, each already averaged over the four origins", "24: four origins times six steps", "4, one per origin, each being that origin''s own mean error", "48, one for every month of EKENE-P1 from month 0 to month 47"]'::jsonb, 1, 'The basis reads "overall metrics average over every origin and step", and origins 24, 30, 36 and 42 each score 6 steps, so 4 x 6 = 24 errors are pooled. The by-horizon view is a separate breakdown, and no origin mean is averaged in its place. Months 0 to 23 are never scored, being training months at every origin.'),
  ('forecastml', 'intermediate', 'module', 'm05-pooling-backtest-errors', 2, 'Pooled over the teaching backtest, holt''s ME is 6.558931. On the teaching hold-out alone it was -4.573069. What does the pooled figure say?', '["The pooled run is wrong, as one method on one well must keep the sign of its bias", "Over the four origins holt forecast low on average, though from origin 36 it ran high", "Holt forecast high over the whole backtest, as a positive ME marks a high forecast each time", "The two figures are the same bias, reported with opposite signs by the two functions used"]'::jsonb, 1, 'An error is actual minus forecast, so a positive ME says the forecasts were low on average; origins 24, 30 and 42 carry mostly positive errors while origin 36, the teaching hold-out''s origin, carries mostly negative ones. Both functions use the same sign rule, and one well can show a bias of either sign depending on the months and origins pooled.'),
  ('forecastml', 'intermediate', 'module', 'm05-pooling-backtest-errors', 3, 'The teaching backtest''s `byHorizon` row for step 1 prints MAE 10.992423. How many errors does that figure rest on?', '["24, every error of the backtest reweighted toward step 1", "6, one for each step of the first origin''s forecast run", "1, the first error of the first origin, at month 24", "4, the step 1 error of each origin"]'::jsonb, 3, '`byHorizon` scores step 1 of every origin together, so with origins 24, 30, 36 and 42 each step has 4 errors: 11.627690, 9.126974, -12.431964 and 10.783063 at step 1. The course warns that a figure on 4 numbers is a small sample. The 24 errors are the overall pool, and a single origin''s run is no by-horizon row.'),
  ('forecastml', 'intermediate', 'module', 'm05-pooling-backtest-errors', 4, 'In the teaching backtest''s by-horizon rows, the MAE reads 10.992423 at step 1, 8.726945 at step 2, 9.044099 at step 3, 7.135803 at step 4, 16.466929 at step 5 and 18.348056 at step 6. Which reading does the course give?', '["The MAE rises at every step, the textbook pattern of a forecast fading with distance", "Step 4 is the method''s best horizon, and the note should say holt forecasts four months best", "Steps 5 and 6 are outliers, to be dropped from the pooled figures before they are quoted", "Step 6 misses by more than step 1, but the steps between do not rise in order"]'::jsonb, 3, 'The step 6 MAE is above step 1 on this well, while step 2 and step 4 are below step 1, so the rows do not rise in order. With 4 errors per step a by-horizon figure is a small sample, so no best horizon is claimed from it, and nothing is dropped from a pooled metric.'),
  ('forecastml', 'intermediate', 'module', 'm05-pooling-backtest-errors', 5, 'At step 3 of the teaching backtest the by-horizon ME and MAE both read 9.044099. What does that say about the four step 3 errors?', '["All four are positive: each origin''s forecast was low three steps out", "All four are negative; the MAE prints the negative mean''s size", "They cancel to zero, so the ME equals the MAE by coincidence of rounding", "Only the origin 36 error is positive, and it dominates both of the means"]'::jsonb, 0, 'The ME equals the MAE only when no error is negative, and the step 3 errors are 23.391678, 6.259443, 3.128846 and 3.396430, all positive, so every forecast was low at step 3. Negative errors would make the ME equal minus the MAE, and cancelling errors would leave the ME below the MAE.'),
  ('forecastml', 'intermediate', 'module', 'm05-pooling-backtest-errors', 6, 'The engine''s pooled MASE for the teaching backtest is 0.374515. How is each error scaled?', '["The first origin''s scale, 36.956522, held fixed for every origin of the run", "The naive error of the six months each origin forecasts", "By the lag-1 naive in-sample MAE of its own origin''s training window", "One mean of the four origins'' scales, taken at the end"]'::jsonb, 2, 'The basis reads "MASE scales each error by its own origin''s lag-1 naive in-sample MAE": origin 24 by 36.956522, origin 30 by 32.003448, origin 36 by 28.045714 and origin 42 by 25.682927. No single scale is used for the run, and the forecast months never set a scale.'),
  ('forecastml', 'intermediate', 'module', 'm05-pooling-backtest-errors', 7, 'Dividing every error of the teaching backtest by the last origin''s scale gives 0.458893 in place of the engine''s 0.374515. Why is it higher?', '["The last origin''s errors are the largest, and its scale is built from them in the process", "The scales fall from origin to origin, so the last origin''s 25.682927 is the smallest divisor", "One scale for all four origins double counts the errors that fall at the shared months", "The last origin''s scale uses lag 12, which on a declining well is the larger scale"]'::jsonb, 1, 'Each origin''s training window has its own Q, 36.956522 falling to 25.682927 at origin 42, so dividing every error by the smallest one inflates the figure. A scale is built from training months, never from errors; the step equals the horizon, so no month is shared; and every scale here is lag 1.'),
  ('forecastml', 'intermediate', 'module', 'm05-pooling-backtest-errors', 8, 'The teaching backtest''s pooled RMSE is 14.083697 and its pooled MAE 11.785709. Which statement holds?', '["Both pool the same 24 errors, and RMSE weights the large ones more by squaring", "RMSE is in percent and MAE in bbl/d, so their gap cannot be read as a size", "RMSE pools the 4 origin means and MAE the 24 errors, hence the larger figure printed", "The gap shows the refitted run leaked, as an honest backtest keeps them equal"]'::jsonb, 0, 'RMSE and MAE are both in bbl/d and both average over every origin and step, the same 24 errors; squaring gives large errors more weight, so RMSE is at least MAE. The gap says nothing about leakage.'),
  ('forecastml', 'intermediate', 'module', 'm05-pooling-backtest-errors', 9, 'The teaching backtest pools MAPE 4.002905 and sMAPE 4.065956. What do these figures describe?', '["The mean of each origin''s MAPE and sMAPE, taken as four figures and averaged once more", "Percentage errors over all 24 forecasts of months 24 to 47, pooled across four origins", "Percentage errors on the training months, the in-sample one-step residuals of each window", "Holt''s MAPE and sMAPE at step 1 alone, being the step the backtest is ranked on"]'::jsonb, 1, 'Overall metrics average over every origin and step, so the pooled MAPE and sMAPE run over the 24 forecast errors on months 24 to 47, in percent. They pool the errors themselves with no origin means in between, score out-of-sample forecasts, and cover every step.'),
  ('forecastml', 'intermediate', 'module', 'm05-pooling-backtest-errors', 10, 'EKENE-P3 is backtested with damped from first origin 6, horizon 6, step 6, refitted. What does the engine return for the overall MASE?', '["Null, because origin 6 trains on the plateau months 0 to 5, whose scale is 0", "A number pooled from the six origins that have a scale, with origin 6 left out", "A refusal naming `firstOrigin`, since an origin inside a plateau is not allowed", "Infinity, the origin 6 errors having been divided by a scale of 0.000000"]'::jsonb, 0, 'Origin 6''s training window is all 1500.000000, so its Q is 0 and `maseScale` is null. One null scale leaves the overall MASE and every by-horizon MASE null, with the reason naming origin 6. The engine drops no origin, accepts the call, and never divides by zero.'),
  ('forecastml', 'intermediate', 'module', 'm05-pooling-backtest-errors', 11, 'In that EKENE-P3 backtest from origin 6, MASE is null. What becomes of the other metrics?', '["Null too, since one null metric voids every pooled figure", "Computed from origin 12 on, the first origin with a scale above 0", "They are numbers: MAE 62.892091 and sMAPE 11.808809", "Refused along with MASE, the call restarting at origin 12"]'::jsonb, 2, 'Only MASE depends on the scale; the other metrics are numbers, MAE 62.892091 and sMAPE 11.808809, over every origin including origin 6. Nothing is refused and no origin is dropped; the null MASE comes with its reason.'),
  ('forecastml', 'intermediate', 'module', 'm05-pooling-backtest-errors', 12, 'The same EKENE-P3 backtest started at first origin 12, past the plateau, gives an overall MASE of 2.004154. What does the course take from the pair of runs?', '["The origin 12 run corrects the first and replaces it", "The runs agree once the null origin is removed", "A MASE above 2 shows damped fails on any well that starts on a plateau", "Choosing the origins is part of the test, so the origins are stated"]'::jsonb, 3, 'Starting past the plateau gives every origin a scale and a pooled MASE of 2.004154; starting at 6 leaves it null. Those are two backtests with different origins, and the course''s rule is to state them. Neither corrects the other, the engine removes no origin, and one well supports no claim about every plateau.'),
  ('forecastml', 'intermediate', 'module', 'm05-pooling-backtest-errors', 13, 'Which reason does the EKENE-P3 damped backtest from first origin 6 give for its null MASE?', '["\"MASE is undefined: insample has 9 values and the lag-1 naive forecast has zero in-sample error on them (every y[t] - y[t - 1] is 0), so the scale is 0\", as `accuracy` gives", "\"MASE needs insample (the training series) to scale by its in-sample naive error\", since a backtest passes no training series of its own to the scaled error at any origin", "\"MASE is undefined: at origin 6 the training window has 6 values and the lag-1 naive forecast has zero in-sample error on them (every y[t] - y[t - 1] is 0), so the scale is 0\"", "A refusal naming `y`, as a series whose first months repeat one rate exactly is not accepted by `backtest`, and the call returns no metrics for any of its origins at all"]'::jsonb, 2, 'A backtest reason names the origin it comes from, so the reason names origin 6 and its window of 6 values, in the engine''s own words. The 9-value reason belongs to an `accuracy` call on the whole plateau, and a backtest builds each origin''s training series itself. The series is accepted.'),
  ('forecastml', 'intermediate', 'module', 'm05-pooling-backtest-errors', 14, 'Across the teaching backtest the training-window scale falls from 36.956522 at origin 24 to 25.682927 at origin 42. What must be true of the months each later window adds?', '["They are shut-in months, whose zero rates pull the naive error of the window down", "They are the months the earlier origins scored, now counted with their errors halved", "Their month-to-month changes are smaller on average than those already in the window", "Nothing about them; the engine shrinks each origin''s scale by a fixed share as it moves"]'::jsonb, 2, 'Q is the mean of |y_t - y_(t-1)| over the training window, so it can fall as a window grows only if the differences added are smaller than the mean before them: on EKENE-P1''s decline the later months change less. EKENE-P1 has no shut-in, a scale is built from rates and never from errors, and no fixed shrink is applied.'),
  ('forecastml', 'intermediate', 'module', 'm05-pooling-backtest-errors', 15, 'At step 2 the teaching backtest''s by-horizon ME is -0.602230 while every other step''s ME is positive. What should a note do with that?', '["Report it as one row of 4 errors, a small sample, and draw no rule from it", "Say holt forecasts high two months out, as a rule for EKENE-P1", "Drop step 2 from the pooled ME, being the only step of opposite sign", "Refit the backtest with step 2 so that the sign agrees with the rest"]'::jsonb, 0, 'Each by-horizon figure rests on 4 errors, one per origin, so a sign at one step is a small-sample reading and no rule. Nothing is dropped from a pooled metric, and the step between origins is a setting of the test that is not chosen to change a sign.'),
  ('forecastml', 'intermediate', 'module', 'm06-methods-compared', 1, 'What does `compareWithArps` hold the same for every method it scores?', '["Only the metrics: each method is free to pick the origins that suit its own fitting length best", "The fitted parameters, which are estimated once on the first window and shared by all", "The origins, the horizon and the metrics, with Arps backtested beside ses, holt and damped", "The forecasts themselves, averaged over the methods before any error is taken from them"]'::jsonb, 2, 'The Professional question is the testing workflow: the same origins, the same horizon, the same metric, for every method, and the comparison backtests ses, holt, damped and the Arps baseline that way. Each method fits its own parameters, and nothing is averaged across methods before scoring.'),
  ('forecastml', 'intermediate', 'module', 'm06-methods-compared', 2, 'On EKENE-P2''s months 0 to 21, before the shut-in (origins 10, 13, 16, 19, horizon 3), how do the methods order by MASE?', '["Arps 0.389192, holt 0.483573, damped 0.504549, ses 1.006754", "Holt 0.483573 first, arps 0.389192 second, ses last", "Holt, damped, arps, ses, as after the workover", "Ses first at 1.006754, the highest MASE"]'::jsonb, 0, 'Ordered by MASE, arps 0.389192 is the lowest, then holt 0.483573, damped 0.504549, ses 1.006754, with arps first before the shut-in. Arps''s 0.389192 is below holt''s, so holt cannot lead; the order after the workover is a different comparison; and a higher MASE is the worse one.'),
  ('forecastml', 'intermediate', 'module', 'm06-methods-compared', 3, 'Over all 48 months of EKENE-P2 (origins 28, 31, 34, 37, 40, horizon 6), after the workover, which method has the lowest MASE, and where does arps stand?', '["Arps, at 0.389192, as it was before the shut-in", "Damped, at 0.599131, with arps second behind it", "Holt, at 0.571171, with arps third at 0.605968", "Arps and holt level, since the two print close to one another"]'::jsonb, 2, 'After the workover the order by MASE is holt 0.571171, damped 0.599131, arps 0.605968, ses 0.789324. 0.389192 is arps before the shut-in, a different window; damped is second; and arps''s 0.605968 is above holt''s 0.571171.'),
  ('forecastml', 'intermediate', 'module', 'm06-methods-compared', 4, 'Why does the Arps baseline fall behind on EKENE-P2 after the workover?', '["The shut-in months are fitted as zeros, which drags the Arps curve down to the floor", "Arps is fitted once on the first window and held, while the smoothing methods are refitted at each origin", "The comparison scores Arps on MAPE alone, and MAPE is null through the shut-in months", "Its fit is a regression on every positive month of each window, the months before the uplift included"]'::jsonb, 3, 'The Arps fit is a regression on every positive month of each training window, including the months before the uplift, so it forecasts too low after the restart: its mean error is -23.147528 bbl/d against holt''s 20.751043. Zero months are dropped before the fit, Arps is refitted on every window, and every method is scored on the same metrics.'),
  ('forecastml', 'intermediate', 'module', 'm06-methods-compared', 5, 'After the workover the Arps baseline''s mean error is -23.147528 bbl/d and holt''s is 20.751043. What does each sign say?', '["Arps low and holt high", "Arps forecast high on average and holt forecast low", "Both forecast high, the signs only marking which method was fitted first", "Arps was the more accurate, being the one with a negative mean"]'::jsonb, 1, 'An error is actual minus forecast, so a negative mean says the forecast sat above the well and a positive mean says it sat below: Arps high, holt low. The sign is the direction of the bias, and it does not say which method is better; that is read from a named metric such as MASE.'),
  ('forecastml', 'intermediate', 'module', 'm06-methods-compared', 6, 'The same EKENE-P2 comparison is started from first origins 26, 28, 30 and 32 after the restart (horizon 6, step 3). What stays the same across the four?', '["Holt ranks first by MASE from each of the four first origins", "Arps stays in third place, behind holt and damped, at every origin", "A smoothing method ranks first by MASE every time", "The best MASE, held close to holt''s 0.571171 whichever origin opens the run"]'::jsonb, 2, 'The first-ranked method is holt from 26, 28 and 32 and damped from 30, so a smoothing method leads each time while which one changes. Arps is second from 26, third from 28 and 30, and last from 32. The best MASE runs 0.573284, 0.571171, 0.461235 and 0.510297.'),
  ('forecastml', 'intermediate', 'module', 'm06-methods-compared', 7, 'From first origin 30 after the restart, the EKENE-P2 comparison orders damped, ses, arps, holt. What does the course conclude from this beside the run from origin 28?', '["Damped is the right method for EKENE-P2, having the lowest MASE of the four first origins, at 0.461235", "The winner depends on the origins, so a ranking is reported with its origins, horizon, step and metric", "The origin 28 run was wrong, as holt should not rank last from a later first origin on the very same well", "Holt is unstable on this well and is dropped from the comparison before any note is written on its ranking"]'::jsonb, 1, 'From origin 28 holt ranks first and from origin 30 last, with damped first at 0.461235: the same methods on the same well order differently as the origins move. The course''s rule is to report a ranking with its origins, horizon, step and metric. One favourable run does not name a method right for the well, and neither run is wrong.'),
  ('forecastml', 'intermediate', 'module', 'm06-methods-compared', 8, 'On EKENE-P1 from first origin 30, horizon 6, step 3, the comparison ranks arps first at MASE 0.199862. Why does the course expect that?', '["Arps always ranks first on a 48-month well, whatever the well''s shape", "The Arps baseline is scored in-sample while the smoothing methods are backtested", "EKENE-P1 was drawn from an Arps curve when the synthetic field was built", "Arps is scored on fewer origins than the others, which flatters its MASE"]'::jsonb, 2, 'The Ekene field is synthetic, and EKENE-P1 was drawn from an Arps curve, so the Arps baseline fitting it best is expected. On EKENE-P2 after the workover arps ranks third, so it does not always lead. Arps is backtested on the same origins as the others, and the order comes from the MASE figures.'),
  ('forecastml', 'intermediate', 'module', 'm06-methods-compared', 9, 'In that EKENE-P1 comparison, how many errors does each method''s row pool?', '["30: origins 30, 33, 36, 39 and 42 each score 6 steps", "24, as in the teaching backtest of holt from origin 24", "6, one per step ahead of the first origin, origin 30", "48, one per month of EKENE-P1 from month 0 to month 47"]'::jsonb, 0, 'First origin 30 with step 3 gives origins 30, 33, 36, 39 and 42, each scoring horizon 6, so each row pools 30 errors. The teaching backtest, with step 6 from origin 24, pools 24; months before origin 30 are never scored.'),
  ('forecastml', 'intermediate', 'module', 'm06-methods-compared', 10, 'What `refit` does `compareWithArps` use when none is given, and what happens to the Arps baseline?', '["Refit false, holding every method''s parameters from the first window, Arps included", "Refit true for the smoothing methods only, with Arps fitted once on all 48 months", "No refit at all: the comparison fits each method on the whole series and scores its residuals afterwards", "Refit true, as in `backtest`, and Arps is refitted on every training window whatever refit says"]'::jsonb, 3, 'The signature reads `refit = true` and `m = 1`, and the EKENE-P1 result returns refit true. The Arps baseline is refitted on every training window whatever refit says. Fitting on all 48 months would let the scored months reach the fit, which the comparison never does.'),
  ('forecastml', 'intermediate', 'module', 'm06-methods-compared', 11, 'In the EKENE-P1 comparison, ses has ME -30.493333 and MASE 1.067547. What does that pair say about ses on this well?', '["Low forecasts, and it beat the in-sample naive forecast by a small margin on average over the run", "Its flat forecast ran high, and its scaled errors averaged above the naive yardstick of 1", "No bias, and a MASE just above 1 marks a method that equals the naive forecast in its size", "High forecasts, yet a MASE above 1 places it first among the four methods"]'::jsonb, 1, 'A negative ME says the forecasts sat above the well on average, as a flat forecast does on a decline, and a pooled MASE above 1 says its errors, each divided by its own origin''s in-sample naive error, averaged above 1. Ses ranks last on this comparison, behind arps 0.199862, damped 0.287529 and holt 0.346480.'),
  ('forecastml', 'intermediate', 'module', 'm06-methods-compared', 12, 'Which set of items belongs in a note written up for a backtest?', '["The origins with horizon and step, refit or held, each metric with its reason when null, MASE with its m and the ranking''s metric", "The best method''s name and its MASE, since the remaining settings of the run can be read back from the engine later on by anyone", "The in-sample MSE of each method with its fitted parameters, which stands in for the backtest when the series is short or new", "Only the pooled MAE in bbl/d over every origin and step, because a single metric keeps the note easy to check and compare"]'::jsonb, 0, 'A backtest note names the well and months, the methods, the first origin, horizon and step and so the origins, refit or held, each metric with its reason when null, MASE with its lag m, and the ranking with the metric it is by. Every figure changes when a setting changes, so a note that leaves one out cannot be checked; an in-sample MSE answers another question.'),
  ('forecastml', 'intermediate', 'module', 'm06-methods-compared', 13, 'A draft note reads "holt is accurate on EKENE-P2". What does the course require in its place?', '["The metric and the months, for example holt''s MASE 0.571171 at m 1 from origins 28 to 40", "Nothing more: holt ranks first after the workover, and the claim can stand in the note as written", "Holt''s in-sample MSE on all 48 months, the fit that the backtest was designed to confirm", "The word \"accurate\" replaced with \"best\", since the ranking settles the matter by itself"]'::jsonb, 0, 'Any statement of how good a forecast is names its metric and its months: holt''s MASE 0.571171 at m 1 over origins 28, 31, 34, 37 and 40, horizon 6. Holt ranks first only from some origins, an in-sample MSE is not a test of forecasting, and "best" still needs its metric and origins.'),
  ('forecastml', 'intermediate', 'module', 'm06-methods-compared', 14, 'A learner compares holt''s MASE 0.241874 on EKENE-P1''s teaching hold-out with its 0.374515 from the teaching backtest and concludes that holt got worse. What is wrong with that reasoning?', '["Nothing; both are MASE at m 1 on EKENE-P1, so the rise shows holt worsening", "The hold-out MASE uses lag 12, which makes it much smaller than the backtest''s", "The backtest MASE is in percent, so it cannot be set against the hold-out", "They are different tests: one origin against four origins pooled"]'::jsonb, 3, 'A hold-out MASE and a backtest MASE of the same method are different tests: the hold-out scores one origin, 36, and the backtest pools 24 errors from origins 24, 30, 36 and 42, each on its own scale. Both are at m 1, and MASE has no unit.'),
  ('forecastml', 'intermediate', 'module', 'm06-methods-compared', 15, 'Ranking EKENE-P2''s methods through its shut-in, why is MASE a workable default where MAPE is not?', '["In bbl/d, MASE keeps the shut-in months on their true scale", "Months after the workover are ignored, so no uplift sways it", "Arps can be scored on MASE alone, the others needing a fit", "MASE stays a number through the shut-in, while MAPE comes back null"]'::jsonb, 3, 'MASE scales by the training months'' naive error, so a zero actual in the scored months does not void it; MAPE divides by each actual and returns null through the shut-in. MASE has no unit, it scores every origin''s months after the workover, and Arps is scored on every metric.'),
  ('forecastml', 'intermediate', 'final', null, 1, 'Damped, fitted on EKENE-P1 months 0 to 35, forecasts month 36 at 283.622932. The well made 270.100000. What sign does the error carry?', '["Positive, the forecast exceeding the actual", "No sign at all, since the engine reports each error as a distance between two rates", "Negative: damped''s figure exceeded what the well produced", "Positive for damped and negative for holt, because a damped method reverses the rule"]'::jsonb, 2, 'The engine''s rule is e = actual - forecast, the same for every method, so 270.100000 less 283.622932 is negative and says the forecast was high. The excess of forecast over rate is minus the error, and the sign is always printed.'),
  ('forecastml', 'intermediate', 'final', null, 2, 'Holt''s error at month 47 of the teaching hold-out is 6.752492, with a forecast of 204.647508 against an actual of 211.400000. What happened at that step?', '["Holt forecast low: the well held up at 211.400000 while holt''s line kept falling", "Holt forecast high by 6.752492 bbl/d, its line sitting above the actual at month 47", "An exact forecast, any error below 10 bbl/d counting as zero", "A residual of the fit, since month 47 was among the months the parameters were chosen on"]'::jsonb, 0, 'A positive error is an actual above the forecast: the well made 211.400000 and holt''s straight line forecast 204.647508. The engine rounds nothing to zero, and month 47 is a hold-out month, so the figure is an out-of-sample error and no residual.'),
  ('forecastml', 'intermediate', 'final', null, 3, 'Which month of the teaching hold-out did holt forecast most closely?', '["Month 46, with an error of -0.027913", "The first step, month 36, being nearest the end of the fit and the easiest to forecast", "At month 43, where the error was 0.730872, the only one below a single bbl/d in size", "Month 38, at 3.128846, where holt forecast low by the smallest margin of any month"]'::jsonb, 0, 'Holt''s errors on months 36 to 47 include 0.730872 at month 43 and -0.027913 at month 46, the smallest in size. Month 36''s error is -12.431964; the errors do not shrink toward the first step; and 3.128846 is larger than both.'),
  ('forecastml', 'intermediate', 'final', null, 4, 'On the teaching hold-out ses forecasts 290.700000 for every one of months 36 to 47. Why is it the same figure each month?', '["The engine holds a forecast fixed across a hold-out so that each month is scored on equal terms", "Ses was fitted with alpha 0, which freezes the level at the first month of the series", "Ses has no trend, so every h-step forecast is the final level of the fit", "The hold-out months are all at one rate, so every method forecasts a flat line on them"]'::jsonb, 2, 'Simple smoothing has no trend state, so its h-step forecast is the final level at every step. Holt and damped change from step to step on the same hold-out, so the engine fixes nothing; the actuals fall from 270.100000 to 211.400000; and nothing here states an alpha of 0.'),
  ('forecastml', 'intermediate', 'final', null, 5, 'On the teaching hold-out, how do the three methods order by RMSE, lowest first?', '["Damped 16.204238, holt 8.360530, ses 55.720702", "Holt 6.783515, damped 14.978829, ses 51.683333", "Holt 8.360530, damped 16.204238, ses 55.720702", "Ses 55.720702, damped 16.204238, holt 8.360530"]'::jsonb, 2, 'The hold-out prints RMSE 8.360530 for holt, 16.204238 for damped and 55.720702 for ses. The figures 6.783515, 14.978829 and 51.683333 are the MAEs, and the other orders put a larger RMSE ahead of a smaller one.'),
  ('forecastml', 'intermediate', 'final', null, 6, 'Holt''s hold-out MAE on EKENE-P1, 6.783515, is well below its in-sample one-step MAE on months 0 to 35, 19.755951. What does the course take from this?', '["The two answer different questions, and the method is judged on the hold-out", "A poor fit, since an honest out-of-sample error should always sit above the in-sample one", "Leakage, as a lower MAE out of sample needs months reaching the fit", "Dividing the in-sample figure by 12 before it can be compared with the hold-out one"]'::jsonb, 0, 'Nothing requires an out-of-sample figure to exceed an in-sample one: they measure different horizons on different months, and on EKENE-P1 holt''s straight line happened to follow months 36 to 47 closely. Leakage is judged by how a figure was made, never by its size, and dividing by 12 turns neither figure into the other.'),
  ('forecastml', 'intermediate', 'final', null, 7, 'Which of these is a residual in the course''s sense?', '["Holt''s error at month 40 of the teaching hold-out, -13.910343", "Holt''s one-step error at month 20 of a fit on months 0 to 35", "Ses''s pooled ME over the teaching backtest''s twenty-four errors", "The difference between two methods'' forecasts for the same month"]'::jsonb, 1, 'A residual is an in-sample one-step error, on a month inside the fitted series. Month 40 is a hold-out month, so its figure is an out-of-sample error; a pooled ME is a metric; and a difference between forecasts involves no actual, so it is no error at all.'),
  ('forecastml', 'intermediate', 'final', null, 8, 'Which sentence meets the course''s rule for stating how good a forecast was?', '["The most accurate method for EKENE-P1 is holt, and it is the one that should be used in every case", "Holt''s MAE on EKENE-P1 months 36 to 47, fitted on months 0 to 35, was 6.783515 bbl/d", "EKENE-P1 was forecast well by holt, with a small error over the months checked", "Holt reached 2.781120, the best figure of the three methods on the well"]'::jsonb, 1, 'The course legislates that a statement of how good a forecast is names its metric and its months: here MAE on months 36 to 47, with the training months named. The other sentences leave out the metric, the months or both; 2.781120 is holt''s MAPE, but the sentence names neither the metric nor the months.'),
  ('forecastml', 'intermediate', 'final', null, 9, 'Which figures are holt''s, damped''s and ses''s MAPE when each is scored on months 36 to 47 of EKENE-P1?', '["Holt 2.735957, damped 6.221199, ses 19.852301", "Damped 6.462737 ahead of holt 2.781120, since damped''s forecast flattens", "All three tie near 2.781120, as MAPE is scaled to each well''s own size", "Holt 2.781120, damped 6.462737, ses 22.550260, all in percent"]'::jsonb, 3, 'MAPE on the teaching hold-out is 2.781120 for holt, 6.462737 for damped and 22.550260 for ses. 2.735957, 6.221199 and 19.852301 are the sMAPE figures. A lower MAPE is the better one, and the three methods differ widely.'),
  ('forecastml', 'intermediate', 'final', null, 10, 'On the EKENE-P2 shut-in hold-out, holt''s sMAPE term is 8.157702 at month 20 and 6.583278 at month 21. Which reading is right?', '["Both months were forecast low, and month 21''s term is smaller because its actual of 364.000000 was larger", "Month 21''s term is smaller because sMAPE halves the term of any month where the forecast ran above the well", "Both terms count 200 at the top, being in the months just before the three months of shut-in at rate 0", "Month 20 was forecast low by 34.471530 and month 21 high by 24.778760, the larger miss giving the larger term"]'::jsonb, 3, 'The errors are 34.471530 at month 20 (actual 439.800000, forecast 405.328470, forecast low) and -24.778760 at month 21 (actual 364.000000, forecast 388.778760, forecast high). The larger miss gives the larger term. sMAPE halves nothing, and only a zero actual with a non-zero forecast scores 200.'),
  ('forecastml', 'intermediate', 'final', null, 11, 'On the EKENE-P2 shut-in hold-out RMSE is 258.102385 against MAE 209.968065. Why is the gap so wide?', '["RMSE counts each shut-in month twice, once for the zero rate and once again for the restart after it", "The three shut-in months carry by far the largest errors, and squaring weights them heavily", "The zero actuals are replaced by the training mean before RMSE is computed", "RMSE is in percent here, since MAPE is null and the engine switches units"]'::jsonb, 1, 'The errors at months 22, 23 and 24 are -372.229050, -355.679339 and -339.129629, far larger than the others, and RMSE squares before it averages, so they lift it well above the MAE. No month is counted twice or replaced, and RMSE stays in bbl/d whatever MAPE returns.'),
  ('forecastml', 'intermediate', 'final', null, 12, 'Holt''s scaled error on EKENE-P2''s shut-in hold-out prints 5.427746. How does that compare holt with the naive yardstick of months 0 to 19?', '["Holt''s MAE on months 20 to 25 was over five times the naive error of its training months", "The MASE was returned as null and printed as a large number in its place", "Holt beat the naive forecast five times over on the months that were scored", "The shut-in months were dropped from the scoring, and so only five of the six months remain in the mean"]'::jsonb, 0, 'MASE is the MAE over the lag-1 naive MAE of the training months 0 to 19, so 5.427746 says the MAE of 209.968065 bbl/d was more than five times that scale, driven by the shut-in misses. A MASE above 1 is worse than the naive yardstick, and no month is dropped.'),
  ('forecastml', 'intermediate', 'final', null, 13, 'Which methods on the teaching hold-out have a MAE below the lag-1 naive in-sample error of months 0 to 35?', '["Holt and damped, at MASE 0.241874 and 0.534086", "All three, since each method forecasts better than a naive forecast of the hold-out", "Ses alone, as its flat forecast is the naive forecast carried over to the months ahead", "Holt only, since damped''s MASE above 0.5 places it level with the naive forecast"]'::jsonb, 0, 'MASE below 1 means the MAE is smaller than the in-sample naive MAE: holt 0.241874 and damped 0.534086 are below 1, and ses at 1.842825 is above it. The yardstick is the in-sample naive error, and 1 is the line, so 0.534086 is below it.'),
  ('forecastml', 'intermediate', 'final', null, 14, 'On EKENE-P5''s low tail, damped and holt are both fitted on months 0 to 35 and scored on months 36 to 47. Damped''s MASE is 0.563761 against holt''s 0.144157, and their MAEs are 12.689466 and 3.244769. Why do the MASEs stand in the same ratio as the MAEs?', '["MASE is the MAE in percent, and a percentage keeps the ratio of any two MAEs", "The engine rescales the MASEs after scoring to match", "Damped and holt share their fitted parameters on this well, and so their errors", "Both are divided by one scale, the naive error of the same training months"]'::jsonb, 3, 'MASE is MAE / Q, and Q depends only on the training series, months 0 to 35 of EKENE-P5 for both methods, so the ratio of the MASEs is the ratio of the MAEs. MASE is no percentage, nothing is rescaled after scoring, and the two methods fit their own parameters.'),
  ('forecastml', 'intermediate', 'final', null, 15, 'A note quotes holt''s MASE on the teaching hold-out as 0.024087 and leaves out the lag. What goes wrong?', '["Nothing, as monthly data has one lag", "The figure is wrong for EKENE-P1", "The figure becomes a MAPE, as a scaled error without its lag is a percentage", "A reader assumes m 1, where the same forecast scores 0.241874"]'::jsonb, 3, '0.024087 is holt''s MASE at m 12, while m defaults to 1, where the same forecast reads 0.241874. The course''s rule is to quote MASE with its m, because the lag is part of the figure. The engine prints whatever the arithmetic gives, and a MASE stays a ratio.'),
  ('forecastml', 'intermediate', 'final', null, 16, 'What does the MASE scale measure, in the words the course uses for it?', '["The MAE the lag-m naive forecast makes on the training series, in-sample", "Mean rate of the scored months, so that each error becomes a share of production", "Standard deviation of the forecast''s own errors over the months being scored", "One-step residuals of the fitted method, their MAE over the months it was trained on"]'::jsonb, 0, 'Q is the MAE of the naive forecast, each month forecast by the month m before, on the training series. The scored months never set it; it is no standard deviation; and it is built from the naive forecast with no part for the fitted method''s residuals, so every method on one training series shares it.'),
  ('forecastml', 'intermediate', 'final', null, 17, 'At origin 30 of the teaching backtest, which alpha, beta and scale Q does the engine print?', '["Alpha 0.684236, beta 0.379743, Q 36.956522", "Alpha 0.667926, beta 0.392686, Q 32.003448", "Alpha 0.663079, beta 0.398667, Q 28.045714", "Alpha 0.655079, beta 0.393438, Q 25.682927"]'::jsonb, 1, 'Refitted on months 0 to 29, origin 30 carries alpha 0.667926 and beta 0.392686, and its training window''s scale is 32.003448. The other rows are origins 24, 36 and 42.'),
  ('forecastml', 'intermediate', 'final', null, 18, 'Across the whole teaching backtest, where does the largest error fall?', '["Origin 36, step 5, at -13.910343, the largest in size", "The last origin, 42, where the step 6 error is 13.266479", "At origin 30, step 6, at 23.158147, six months from the origin", "At origin 24, step 6, where it is 31.937659"]'::jsonb, 3, 'Origin 24''s errors run up to 31.937659 at step 6, above origin 30''s 23.158147, origin 42''s 13.266479 and origin 36''s -13.910343. All of them are course figures, and 31.937659 is the largest in size.'),
  ('forecastml', 'intermediate', 'final', null, 19, 'The course''s honest one-step run on EKENE-P1 moves holt forward one month at a time from origin 36, horizon 1, refitting each time. How many forecasts does it score?', '["12, origins 36 to 47, each forecasting one month", "4, origins 36, 38, 40 and 42", "1, origin 36, which forecasts months 36 to 47 in one run", "48, one per month"]'::jsonb, 0, 'With horizon 1 and step 1 the origins run 36, 37 and on while o + 1 <= 48, so the last is 47, 12 origins, each scoring its own month; the MAE over those months is 8.096036. A single origin forecasting 12 steps is the hold-out, and origins before 36 are not in this run.'),
  ('forecastml', 'intermediate', 'final', null, 20, 'A backtest of holt on EKENE-P1 uses first origin 24, horizon 6 and step 3. How do its forecast windows sit against one another?', '["They tile the series exactly, each month forecast once, as in the teaching backtest", "They overlap: each origin forecasts 6 months, and the next origin starts only 3 months later", "Gaps open between them, three months left unforecast after every origin in turn", "They are refused, since a step shorter than the horizon is not accepted by the engine"]'::jsonb, 1, 'Origin o forecasts months o to o + 5, and with step 3 the next origin is o + 3, so months o + 3 to o + 5 are forecast twice, once from each origin. The teaching backtest tiles because its step equals its horizon, 6. A gap would need a step longer than the horizon, and the EKENE-P2 comparisons after the workover run horizon 6 with step 3.'),
  ('forecastml', 'intermediate', 'final', null, 21, 'A backtest is passed `refit` as a word where true or false belongs. What comes back?', '["The refitted run, any word but false read as true", "The held run, as the engine defaults to held when refit cannot be read", "A refusal naming `refit`: \"refit must be true or false\"", "Both runs side by side, so the learner can choose between them afterwards"]'::jsonb, 2, 'The engine refuses by name in its own words. It does not interpret the word as true or false or return both runs; refit true is the default only when refit is left out.'),
  ('forecastml', 'intermediate', 'final', null, 22, 'Ses has no trend state. What happens when a learner hands its backtest a beta anyway?', '["A backtest of holt, since a beta implies a trend and the engine switches method", "A refusal naming `beta`: \"beta applies to ''holt'' and ''damped'' only: ''ses'' has no trend\"", "The ses backtest with the beta ignored and a note saying it was not used", "A ses backtest in which beta damps the level in place of alpha at every origin"]'::jsonb, 1, 'Ses has no trend state, so a beta has nothing to weight and the call is refused by name. The engine switches no method and ignores no input silently; beta weights only a trend.'),
  ('forecastml', 'intermediate', 'final', null, 23, 'Scoring a forecast with `accuracy`, a learner leaves the actuals empty. How does the call end?', '["Every metric returned as 0, since no month means no error to average", "Null for each metric, with the reason that nothing was scored, in `notes`", "Scores against the insample months, used in place of the missing actuals", "A refusal naming `actual`: \"actual has 0 values: at least 1 actual is needed\""]'::jsonb, 3, 'The engine refuses and names the field in its own words; at least 1 actual is needed. A refusal returns no metrics, so none comes back as 0 or as null, and the training series is never scored in place of the actuals.'),
  ('forecastml', 'intermediate', 'final', null, 24, 'A `compareWithArps` call on EKENE-P1 has month 5 set to null. What does the engine do?', '["Month 5 is dropped, and every method runs on the other 47 months of the series", "It refuses by name: \"y[5] must be a finite number: fill or drop missing values first\"", "A fill of month 5 from months 4 and 6, noted in the result", "Arps runs, as it drops missing months, and only the smoothing methods are refused by name"]'::jsonb, 1, 'A missing month is refused by name at the first index it meets, counting from 0; nothing is filled or dropped, and the caller decides how to condition the series. The refusal covers the whole call.'),
  ('forecastml', 'intermediate', 'final', null, 25, 'Why does the course say the answer to testing rows that are not a time series lies in another course?', '["The engine offers a random split for rows, taught in the data quality course", "The machine learning course''s split by whole wells is the answer for such rows", "Rows that are not a time series are scored by MAPE only, in the decline curve course", "A random split of months is honest for smoothing, and other courses only extend it"]'::jsonb, 1, 'The engine has no random split, because smoothing runs along an unbroken series and is tested honestly only from an origin with all later months withheld. Rows that are no time series are the machine learning course''s subject, which splits them by whole wells. Picking months at random would put later months into the fit.'),
  ('forecastml', 'intermediate', 'final', null, 26, 'In the teaching backtest''s by-horizon rows, step 1 prints MAE 10.992423 and RMSE 11.060437. Why are the two so close?', '["Step 1 carries a single error, and for one error RMSE and MAE are equal", "Both are scaled by the same Q, which pulls the two figures together at step 1 and at no other step", "RMSE at step 1 is taken as the MAE plus a fixed allowance for rounding", "The four step 1 errors are of similar size, so squaring adds little weight to any one"]'::jsonb, 3, 'The step 1 errors are 11.627690, 9.126974, -12.431964 and 10.783063, all near 11 in size, so RMSE is barely above MAE. Each step carries 4 errors, neither metric is scaled by Q, and nothing is added for rounding.'),
  ('forecastml', 'intermediate', 'final', null, 27, 'Which step of the teaching backtest''s by-horizon rows has the lowest MASE, and which the highest?', '["Step 1 lowest at 0.365737 and step 6 highest, the MASE rising in order", "Step 2 lowest at 0.295972, step 5 highest at 0.515369", "Step 4 lowest at 0.231002, step 6 highest at 0.570926", "Step 3 lowest, where the ME equals the MAE at 9.044099"]'::jsonb, 2, 'The by-horizon MASE reads 0.365737, 0.295972, 0.268086, 0.231002, 0.515369 and 0.570926 for steps 1 to 6: lowest at step 4, highest at step 6, and not in order. With 4 errors per step each figure is a small sample.'),
  ('forecastml', 'intermediate', 'final', null, 28, 'Five steps out, the four origins'' errors average 9.511758 with their signs kept and 16.466929 without them. What does the difference between those two means reveal?', '["Every step 5 error is positive, and the gap comes from rounding", "Step 5 carries more errors than the other steps, which spreads them", "Step 5 has errors of both signs, so the signed mean partly cancels", "The MAE includes the scale Q, and the ME does not, at every step"]'::jsonb, 2, 'The ME equals the MAE only when no error is negative; at step 5 origin 36''s error is -13.910343 while the other three are positive, so the mean partly cancels. Every step carries 4 errors, and neither metric includes Q.'),
  ('forecastml', 'intermediate', 'final', null, 29, 'With parameters held from the first window, the teaching backtest pools ME 6.596911, MAE 11.639525 and RMSE 13.997928, against 6.558931, 11.785709 and 14.083697 refitted. What does the course do with the two sets?', '["Average them, since two honest runs of one method should be pooled into one figure", "Report the one that was run and say whether it was refitted or held", "Prefer the held set, whose lower MAE shows that refitting overfits each window", "Discard both, as two honest procedures that disagree cannot be quoted at all"]'::jsonb, 1, 'Held parameters test one parameter set on later data; refitting tests the whole procedure. Both are honest, and a note names which was run. A lower MAE on one well proves no general rule, and the two sets are not averaged.'),
  ('forecastml', 'intermediate', 'final', null, 30, 'Of the seven origins in EKENE-P3''s damped run from 6, one prints `maseScale` 18.163636. Which is it, and why is its scale small?', '["Origin 6, the first, whose window is the plateau and whose scale is small", "Origin 42, the last, whose window is longest and so steadiest", "Origin 12, whose window adds three declining months to the plateau", "Origin 18, as the scale doubles at each origin after the plateau"]'::jsonb, 2, 'Origin 6''s scale is 0 (`maseScale` null), and the other origins read 18.163636, 37.629412, 38.791304, 36.041379, 35.505714 and 33.797561 for origins 12 to 42. Origin 12 trains on months 0 to 11, the nine plateau months and three declining ones, so its mean difference is small. Origin 42''s scale is 33.797561, and origin 18''s is 37.629412, which is no doubling.'),
  ('forecastml', 'intermediate', 'final', null, 31, 'Started past EKENE-P3''s plateau, at first origin 12, damped pools a scaled error of 2.004154. Against the naive yardstick, how did it do?', '["Damped beat the naive yardstick twice over on EKENE-P3 once past the plateau months", "The figure counts the null origin 6 as a zero and doubles the rest to compensate for it", "Two origins returned null scales, and the engine divided the pooled MASE by 2 to match", "Its errors, each over its own window''s naive error, averaged about twice that yardstick"]'::jsonb, 3, 'The pooled MASE divides each error by its own origin''s in-sample naive error and averages; above 1 means the errors ran larger than that yardstick, and 2.004154 is roughly double. Origin 6 is not in a run that starts at 12, so no null scale enters, and the engine applies no correction.'),
  ('forecastml', 'intermediate', 'final', null, 32, 'Scored in percent on EKENE-P2 before the shut-in, over months 0 to 21, which method misses least by MAPE?', '["Arps, at 3.702719 percent", "Holt, at 4.616605 percent", "Damped, at 4.747889 percent", "Ses, at 9.211623 percent"]'::jsonb, 0, 'The before-shut-in rows print MAPE 9.796323 for ses, 4.616605 for holt, 4.897800 for damped and 3.702719 for arps, the lowest. 4.747889 is damped''s sMAPE and 9.211623 ses''s sMAPE.'),
  ('forecastml', 'intermediate', 'final', null, 33, 'After the workover on EKENE-P2 (origins 28, 31, 34, 37, 40, horizon 6), holt has the lowest MASE while damped has the lowest sMAPE, 9.770766. What follows for a write-up?', '["Quote damped as best, as sMAPE is the symmetric metric and so the fairer one", "Average the two metrics, since one of them alone cannot decide the order", "Name the metric a ranking is by, since two metrics can put different methods first", "Report holt as best on every metric, MASE being the one the engine prints"]'::jsonb, 2, 'The rows print sMAPE 9.770766 for damped against holt''s 10.338085, while holt''s MASE 0.571171 is below damped''s 0.599131. The course''s rule is that a ranking is reported with its metric; the comparison orders by MASE unless told otherwise. No metric is averaged with another, and holt does not lead on every metric.'),
  ('forecastml', 'intermediate', 'final', null, 34, 'After the workover, ses ranks last on EKENE-P2 by MASE, at 0.789324. Which reading is right?', '["A last place means its MASE must be above 1, so the figure of 0.789324 is misprinted", "Ses fails the naive yardstick, being the only method of the four ranked below Arps", "Its MAE was below the naive in-sample error even so; last is relative to the other three", "Ses was scored on fewer origins than the other three methods, which placed it last"]'::jsonb, 2, 'A MASE below 1 means the MAE is smaller than the in-sample naive MAE (here below the scale of every origin), whatever the rank; ses is last because the other three are lower still. Every method is scored on the same origins, and a place in a ranking says nothing on its own about the naive yardstick.'),
  ('forecastml', 'intermediate', 'final', null, 35, 'From first origin 26 after the restart, the EKENE-P2 comparison orders holt, arps, ses, damped. What are holt''s and arps''s MASE there?', '["Holt 0.571171, arps 0.605968", "Holt 0.510297, arps 0.742389", "Holt 0.461235, arps 0.646876", "Holt 0.573284, arps 0.702535"]'::jsonb, 3, 'From first origin 26 (origins 26, 29, 32, 35, 38, 41) the best MASE is holt''s 0.573284 and arps''s is 0.702535. 0.571171 and 0.605968 belong to first origin 28, 0.510297 and 0.742389 to 32, and 0.646876 is arps from 30, where damped leads at 0.461235.'),
  ('forecastml', 'intermediate', 'final', null, 36, 'From first origin 32 after the restart (horizon 6, step 3), where does the Arps baseline stand on EKENE-P2?', '["First, at 0.389192, as it was before the shut-in months", "Fourth of four, with MASE 0.742389", "Second, behind holt, as it was from first origin 26 on", "Third, behind holt and damped, as from origin 28"]'::jsonb, 1, 'From first origin 32 the order by MASE is holt, damped, ses, arps, with arps at 0.742389. 0.389192 is arps before the shut-in, and second and third are its places from first origins 26 and 28.'),
  ('forecastml', 'intermediate', 'final', null, 37, 'Holt''s MASE is 0.346480 in the EKENE-P1 comparison from first origin 30 and 0.374515 in the teaching backtest. Why do the two differ?', '["Held parameters from the first window in the comparison, while the backtest refits them", "Lag 12 in the comparison''s MASE against lag 1 in the backtest throughout", "Scoring against Arps, the comparison divides holt''s MASE by the Arps error", "The origins differ: 30, 33, 36, 39, 42 with step 3 against 24, 30, 36, 42 with step 6"]'::jsonb, 3, 'Both are refitted at m 1, the defaults, so the difference comes from the origins and step: the comparison scores origins 30 to 42 with step 3, and the teaching backtest origins 24 to 42 with step 6. MASE is divided by each origin''s naive error, never by another method''s.'),
  ('forecastml', 'intermediate', 'final', null, 38, 'In the EKENE-P1 comparison from first origin 30, the Arps baseline has ME -0.407739 and MAE 5.668226. What does the pair say?', '["Its errors were nearly balanced in sign, with a small mean miss of 5.668226 bbl/d", "It forecast high at every origin and at every step, since its mean error is negative", "Unbiased and exact, both of its figures sitting below a single bbl/d at every origin", "Its MAE is the size of its ME, so every error had one sign"]'::jsonb, 0, 'An ME near 0 with a larger MAE says positive and negative errors largely cancelled, while the mean size of a miss was 5.668226 bbl/d. A negative ME only says high on average, the MAE of 5.668226 bbl/d is far from below a single bbl/d, and the ME is far smaller than the MAE in size.'),
  ('forecastml', 'intermediate', 'final', null, 39, 'In the course''s testing workflow on EKENE-P1, what is done before any method is fitted?', '["The Arps baseline is fitted first, so the smoothing methods can be compared against its curve", "The origins are chosen to favour the method expected to win, and then the series is read", "The series is read and checked: a missing month is refused by name, and a shut-in or plateau is noted", "Every method is fitted on all 48 months to find the parameters the backtest will hold"]'::jsonb, 2, 'The first step reads the series: 48 months, no missing month. A missing month is refused by name, and a shut-in or a plateau changes what the metrics can say. The comparison with Arps comes last, the origins are stated and never chosen to favour a method, and fitting on all 48 months would leak.'),
  ('forecastml', 'intermediate', 'final', null, 40, 'The EKENE-P1 comparison from first origin 30 orders arps, damped, holt, ses. What does the course say the result means for a smoothing method on that well?', '["Arps should be replaced, a smoothing method needing no decline model", "It has not earned its place there against the decline curve baseline", "Wrong on every well, the baseline having ranked first here", "Level with Arps, the four MASE figures being too close to separate"]'::jsonb, 1, 'EKENE-P1 was drawn from an Arps curve, and arps ranks first at 0.199862 against damped 0.287529 and holt 0.346480. The course reads this as a smoothing method not having earned its place on this well. One well supports no claim about every well, and the figures are well apart.'),
  ('forecastml', 'intermediate', 'final', null, 41, 'Why does it matter how a backtest''s errors are scaled when its MASE is pooled?', '["One scale for every error gives a different figure: 0.458893 in place of 0.374515 on the teaching backtest", "The engine pools with one scale by default, the last origin''s, so the note must flag the rare runs that do not", "Each origin''s own scale is the wrong method, and a note that uses it must say so beside the pooled figure", "MASE pooled either way gives the same figure, and the note records the choice of scale only for form''s sake"]'::jsonb, 0, 'The engine scales each error by its own origin''s naive MAE; dividing every error by the last origin''s scale instead gives 0.458893 against the engine''s 0.374515. The two differ, and the engine''s per-origin scale is its stated rule.'),
  ('forecastml', 'intermediate', 'final', null, 42, 'Writing up damped on EKENE-P3 from origin 6, where the scaled error came back null, which line is correct?', '["MAE 62.892091 bbl/d and sMAPE 11.808809 percent, with MASE returned as null and the reason quoted", "0.000000 for MASE, since origin 6 scored no scaled error and the six other origins are averaged", "MASE 2.004154, taken from the run started at origin 12 and quoted for this run from origin 6", "Nothing on MASE, left out of the note without comment since a null has nothing in it to report"]'::jsonb, 0, 'Each metric the engine could not give is reported with its reason from `notes`, and the other metrics are numbers: MAE 62.892091 and sMAPE 11.808809. 2.004154 belongs to a different backtest, from origin 12, and would be labelled as such; a null is never printed as 0.');
